        c = _c;
    }

    function run(uint sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        uint potBefore = c.pot();
        uint cBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;

        bool reverted;
        try c.play{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint potAfter = c.pot();
        uint cBalAfter = address(c).balance;
        uint thisBalAfter = address(this).balance;

        if (!reverted) {
            // successful call: exact ticket payment, pot gained the ticket
