            if (potAfter == 0 && cBalAfter + thisBalAfter == cBalBefore + thisBalBefore && thisBalAfter > thisBalBefore) {
                assert(thisBalAfter - thisBalBefore == potBefore + sendAmount - 1);
            }
        }
    }

    receive() external payable {}
}

