contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount == 10, "amount must equal ticket");
        require(address(this).balance >= amount, "insufficient balance");

        uint prePot = c.pot();
        address preBank = c.bank();
        uint preBankBal = preBank.balance;
        uint preContractBal = address(c).balance;

        bool reverted;
        try c.play{value: amount}() { reverted = false; } catch { reverted = true; }

        uint postPot = c.pot();
        address postBank = c.bank();
        uint postBankBal = postBank.balance;
        uint postContractBal = address(c).balance;

        // In a win: pot is paid to msg.sender (the test contract) and fee to bank.
        // In a loss: pot keeps growing.
        // Combined Ether (contract + bank) can decrease only if the pot is paid to the test contract,
        // which is not accounted for in this combined sum. We check that bank + contract never decrease
        // net of any pot payout: any solvency is implied by the logic.
        // General rule: if the play succeeds and no win occurred (pot increased),
        // then the combined balance increases by the ticket.
        assert(
            reverted ||
            (postBank == preBank && postContractBal + postBankBal >= preContractBal + preBankBal - prePot) &&
            (postPot <= prePot + amount)
        );
    }

    receive() external payable {}
}

